INSERT INTO "meta" VALUES('current_scope','{"authorization_interpretation":"Current directive authorizes implementation and bounded execution toward the selected solver. Older NOT_AUTHORIZED records describe their earlier scopes and are not a request for permission again. Concrete input, resource, runtime and evidence gates still apply.","authorized_current_actions":["Read related project databases and artifacts in Drive, Dropbox and prior attachments","Implement additive exact-arithmetic composition, endpoint task adapter and native interior driver","Run bounded analytical/synthetic verification in this workspace","Prepare exact Frozen107 task plans and, if feasible within a separately recorded finite process cap, run a selected endpoint-only component","Publish additive source and evidence to the same branch and create dual backups"],"base_head":"72ff754814c24e6993092944f5159d400129ae23","branch":"research/r31ao-unequal-order-ladder-20260930","date_utc":"2026-10-01","independent_review_admitted":false,"original_prompt_sha256":"70071962a6b3dc3cfc0c01034c0d1b6f57711833957510a77b0bb6c4e453969e","production_admitted":false,"runtime_identity":"This workspace is not the requested 64-core/128-GB NCP host. Any workspace result must state that distinction.","schema":"WU088_PRODUCTION_IMPLEMENTATION_SCOPE_V1","scientific_admission":false,"scientific_target":"Frozen107 continuous D target, z=3/4, transverse=2; stored inputs and models unchanged","stop_on":["unverified input identity","native backend unavailable or unverified","resource exhaustion","incomplete primitive coverage","historical ABI authority absent"],"unchanged_constraints":["No new order/geometry, R31AK retraining, old B192 producer rerun or comparator rerun","No replacement of historical arrays, donor coefficients, normalization or independently stored model K","No precision downgrade, fast-math, tolerance relaxation or hidden screening","No automatic full49, trajectory, independent-review or production promotion"],"user_directive":"이론/수치설계를 production solver 수준까지 우선 구현하고 돌리고 싶어. 드롭박스/구글 드라이브에 있는 관련 데이터베이스들을 전부 다시 조사하고 맨 처음 프롬프트가 제시한 연구 단계들을 모두 다 진행했는지 다시 한번더 점검해줘."}');
