INSERT INTO "stage_audit" VALUES('G0','SSOT / DATABASE INTAKE','REINVESTIGATED_WITH_EXPLICIT_RECOVERY_GAPS','not applicable','Existing v3 acquisition DB and source ledgers','Both providers queried; selected DB bytes read and integrity checked','Original Deep Research DB not recovered; some archive byte transport blocked. Current audit DB is a new evidence index, not the lost original.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G1','THEOREM COMPLETION','ABSTRACT_SOURCE_BOUND_THEORY_CLOSED_WITH_EXECUTION_PREMISES','T1–T5 source-specific constructions and review preserved','Only part of T1/T2/T4 constructive algorithms is executable; preferred Petras path can use native validated callback instead','Exact witness/component checks exist, not an actual HH enclosure','Discharge actual backend/domain/cost premises; T1 full M and T2/T4 general fallback controllers are not production implementations.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G2','EXACT RAW / ABI DECODER','COMPONENT_VERIFIED_HISTORICAL_AUTHORITY_OPEN','Exact NPY bit decoding and memory order mapped','Exact dyadic decoder and separately pinned binary64 Frozen107 adapter exist','Synthetic decoder checks; Frozen107 byte recovery is distinct from B192 extended-precision decoding','Historical longdouble/complex producer layout admission and actual B192 decode. A current machine probe cannot prove historical layout.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G3','EXACT GRAM / GAP ENGINE','COMPONENT_VERIFIED_ACTUAL_GAPS_PENDING','Exact small Gram and outward radicals; stored model K remains independent','Existing exact Gram engine reused by hash in new composition API','Analytical fixtures and independent PSD checks','Admitted actual raw/model matrices and actual represented gap intervals; no historical SVD-machine error claim from exact norm alone.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G4','VALIDATED SPECIAL-FUNCTION / FIELD CALLBACK','NATIVE_SOURCE_EXISTS_BACKEND_RUNTIME_OPEN','Entire-box analyticity and source-field mapping','Arb/Acb callback plus new native primitive driver candidate','Native compile/run absent in current workspace; unavailable prerequisites documented','Pinned source-to-binary build, callback analytic toy tests and actual primitive acceptance on target host.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G5','ENDPOINT MAJORANT EVALUATOR','EXACT_COMPONENT_IMPLEMENTED_ACTUAL_FULL_TARGET_PENDING','Disjoint complement and Gaussian field majorants','Existing rational engine plus new indexed donor-sum endpoint adapter','Actual source task0 completed for coarse window; additional bounded cutoff attempts and representation-limit fixes are recorded in runtime evidence.','Select decision-budget-sufficient cutoffs for all required primitives; an endpoint bound alone is not a full-domain ball.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G6','COMPACT INTERIOR ENCLOSURE PILOT','NATIVE_DRIVER_CANDIDATE_ACTUAL_FEASIBILITY_UNMEASURED','Whole-outer-box nesting and conditional feasibility','Nested Petras wrapper plus indexed compact worker candidate','No actual accepted native interior enclosure on this workspace','Build and validate serializer/backend; measure actual callback refusals, achieved radii and cost under finite caps.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G7','FULL D CERTIFICATE','OPEN_NO_ACTUAL_FULL_D_BALLS','Post-integral source-prescribed assembly known','Existing assembly plus new strict primitive join/coverage, generated full-domain initializer and native final assembly/export candidate','Zero accepted full-domain 2592-primitive certificate sets; no actual D entry balls','Compile and validate native assembly/export; acquire all2592 accepted actual primitive records, join endpoint once, run source-prescribed assembly and exact final entry export.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G8','FROZEN DECISION CERTIFICATE','CONDITIONAL_COMPOSITION_IMPLEMENTED_ACTUAL_DECISION_PENDING','Sharp C/R/K residual and frozen sufficient conditions','New bounded exact JSON composition CLI/API with direct continuous gaps and represented-gap tubes','Synthetic/analytical cases plus independent exact PSD probes, not actual HH decision','Actual target disks, admitted raw/model inputs, certified epsilon and final scientific review; historical machine replay remains separate.','solver:audit/STAGE_AUDIT.json');
INSERT INTO "stage_audit" VALUES('G9','ADVERSARIAL / INDEPENDENT REVIEW','COMPONENT_REVIEWS_PRESENT_FINAL_SCIENTIFIC_REVIEW_OPEN','Existing theorem reviews preserved','Independent code/math review of newly runnable composition','Component review only','Independent final certificate/physical production decision review after actual numerical evidence; admitted=false.','solver:audit/STAGE_AUDIT.json');
